      const doctor = await nativeDoctorCommand([name], root);
      expect(doctor.data).toMatchObject({
        healthy: false,
        findings: [{ code: `sdk-projection-lock-${expected}` }],
      });
      expect(acquireLock).not.toHaveBeenCalled();
      expect(await files(root)).toEqual(before);
    },
  )

